    index[node] = 0
    stack = []
    def discovery(node):
        nonlocal temps
        temps = node
        visited[node] = True
        stack.append(node)
        for neighbor in neighbors[node]:
            if not visited[neighbor]:
                temps = min(discovery(neighbor), temps)
            elif neighbor not in stack:
                temps = min(temps, index[neighbor])
        if temps < index[node]:
            parent[node] = temps
        return temps

    def stable(node):
        visited[node] = True
        temps = sys.maxsize
        for neighbor in neighbors[node]:
            if index[node] - index[neighbor] == 1 and not visited[neighbor]:
                temps = min(stable(neighbor), temps)

        for neighbor in neighbors[node]:
