from math import gcd
from itertools import accumulate
from functools import reduce

def extended_gcd(a, b):
    """Extended Euclidean Algorithm to find the coefficients x, y such that ax + by = gcd(a, b)"""
    if b == 0:
        return (1, 0)
    x, y = extended_gcd(b, a % b)
    return (y, x - (a // b) * y)

def binomial_coefficient(n, k):
    """Efficient calculation of binomial coefficient (n choose k) using modular multiplicative inverse"""
    coefficients = [0] * (k + 1)
    coefficients[0] = 1
    for i in range(1, n + 1):
        for j in range(min(i, k), 0, -1):
            coefficients[j] = (coefficients[j] * i) % 998244353
    return coefficients[k]

def solution(k, c, n, nums):
    MOD = 998244353
    from operator import xor

    input_list = sorted([2 ** i - k + min(nums), nums[k:]] + [0] * (n - k - 1))
    prev = input_list[0]
    for i in range(1, n - k):
        prev ^= input_list[i]

    odds, evens = [0] * 2, [0] * 2
    odds[prev.bit_length() % 2], evens[prev.bit_length() % 2] = 1, 0

    for digit in range(31):
        evens[prev ^ (1 << digit)] = odds[prev ^ (1 << digit)] + accumulate(prev) % MOD
        odds[prev ^ (1 << digit)] = binomial_coefficient(2 ** (digit + 1), 1 - 2 ** digit) * odds[prev ^ (1 << digit)] % MOD

    return [i * evens[i % 2] % MOD for i in range(2 ** c)][::-1]


