import numpy as np
from functools import lru_cache

def optimal_path_energy(p):
    return sum(p[i] * p[-i-1] for i in range(len(p) // 2))

def reorder_leaves(r1, r2):
    n = len(r1)
    w1 = np.arange(n) * r1 / sum(r1)
    w2 = np.arange(n) * r2 / sum(r2)

    @lru_cache(None)
    def dp(i, j, w):
        if i == n:
            return 0

        if j == n:
            j = i
        # Calculate the cost if we don't pick the box or if we do pick the box
        return max(w1[i] * (optimal_path_energy(w[:i]) + w[i + 1:])) + max(w2[j] * optimal_path_energy(w[:j]) + w[j + 2:],
                                                                           0)

    return dp(0, 0, np.concatenate((w1, w2)))

if __name__ == "__main__":
