def find_minimal_subsequence(n, k, nums) -> str:
    if n == 1:
        return str(n) + " " + str(0)

    max_power, division_needed = [0] * 123, [False] * 123
    prefix_total = 0

    for i in range(n):
        for power in range(25):
            if ((1 << power) & nums[i]) != 0:
                max_power[prefix_total + power] += 1
                division_needed[prefix_total + power] = True

        division_needed[prefix_total] = True
        prefix_total += max_power[prefix_total]

    # Check if it's possible to divide the array's product by k
    if all(value <= 1 for value in max_power):
        return find_div(count(compute_combinations(prefix_total), k, n))

    # Sort the indices according to their power values with descending order
    ordered = [i for i, value in enumerate(compute_combinations(prefix_total)) if value <= 1]
    division_preced_zeros = []
    more_split_zeros = 0
    for i in range(len(ordered)):
        include_final_zero = True if i == len(ordered) - 1 else False
        division_value = tuple([order for order in max_power if order >= 1])
        if divmod(k, value).q <= division_value[-1] <= k:
            division_preced_zeros.append(1 if include_final_zero else 0)
        elif len(value) >= 1:
            more_split_zeros += len(value) * (value[-1] <= division_value[-1])

    if sum(division_preced_zeros) == len(max_power):
        return find_div(count(compute_combinations(prefix_total), k, n))

    if more_split_zeros < 0:
        first_zero = division_preced_zeros.index(max(division_preced_zeros))

    else:
        first_zero = division_preced_zeros.index(min(division_preced_zeros))

    # Choose the first zero's length and see which elements to pick
    first_split_zero = []
    for take in division_needed:
        if tuple([order + 1 for order in range(
            give_back_number(take, first_zero, more_split_zeros, 0)
        )]) in max_power:
            first_split_zero.append(take)

    first_split_zero.sort()
    return str(len(first_split_zero)) + ''.join(map(str, first_split_zero))

# Helper function to compute combinations
def compute_combinations(target_sum):
    nums, result = [], []
    for power, _ in enumerate(max_power):
        if target_sum - power > 0 and max_power[target_sum - power] > 0:
            nums.append(target_sum - power)
            result.append(max_power[target_sum - power].copy())
    return nums, result

def count(result, k, n):
    coefficient = 1
    for c in result:
        coefficient %= k
        k *= c
    return coefficient

def find_div(combination):
    total, taken = 0, 0
    for take in combination:
        total += take
        taken += take * min(combination)
    if not taken > total - 1:
        sum_subseq = taken - int(math.log2(sum(combination - 1)))
        if sum_subseq < 1:
            sum_subseq = 1
    else:
        sum_subseq = 1
    return sum_subseq + 1

