def is_feasible(n, m, r1, c1, r2, c2, actions):
    if r1 == r2 and c1 == c2:
        print("Yes")
        return True
    for t, r, c in actions:
        if t == 1 or t == 2:
            if can_place_barriers(n, m, r1, c1, r2, c2, t) or (
                t == 1 and r1 != r2 != 1
            ):
                return True
        elif t == 3:
            if can_walk(n, m, r1, c1, r2, c2, t):
                return True
    print("No")
    return False

def can_place_barriers(n, m, r1, c1, r2, c2, t):
    opposite_row = r1 == r2 and c2 <= c1
    opposite_col = r2 <= r1 and c1 <= c2
    if not (opposite_row or opposite_col):
        return False
    if opposite_row or opposite_col:
        # Check if we can place barriers to form a rectangle
        return r1 < r2 < m and c1 < c2 < m and is_adjacent(r1, c1, r2, c2) and (
            (t == 1 or (r1 == r2 and c1 != c2)) or (t == 2 and not can_place_barriers)
        )
    return False

def can_walk(n, m, r1, c1, r2, c2, t):
    if t == 3:
        t_ms = []
        r = r2
        for c in range(c1, c2):
            t_ms.append((r, c))
            if t == 3:
                if not is_interference(r, c, r1, c1, t_ms):
                    return True
        return False
    elif t == 1:
        t_db = []
        if (r2 - r1) == 0 or (c2 - c1) == 0:
            return False
    return is_interference(r1, c1, r2, c2, t_ms) and (c2 - c1 == 1 or c1 == c2) and is_adjacent(r1, c1, r2, c2)

def is_interference(r1, c1, r2, c2, rbs):
    for rr, cc in rbs:
        if rr == r1 and cc == c1 and r2 <= rr <= r2 < 2 or r1 <= rr - 1 and cc < c2 and c1 < cc - 1:
            return True
        if rr == r2 and cc == c2 and c2 < cc + 1 < c2 < 2 or cc >= c1:
            return True
    return False

def is_adjacent(r1, c1, r2, c2):
    if r1 == r2:
        return 0 <= (c2 + (r2 == r1))[0] <= 2500
    elif c1 == c2:
        return 0 <= (r2 + (c2 == c1))[0] <= 2500
    return False


