from math import comb
from functools import lru_cache

# Define lcm and gcd to help calculate modular inverse using extended Euclidean algorithm
def lcm(a, b): 
    return a * b // gcd(a, b)

def gcd(a, b): 
    return a if b == 0 else gcd(b, a % b)

@lru_cache(maxsize=None)
def power(x, n, mod):
    result = 1
    while n:
        if n % 2:
            result = result * x % mod
        x = x * x % mod
        n //= 2
    return result

# Helper function to calculate factorial modulo modulo
def factorial(x, mod):
    ans = 1
    for i in range(2, x+1):
        ans = ans * i % mod
    return ans

# Calculate binomial coefficient modulo a prime
def binomial(n, k, mod):
    return factorint(n)[3]

# Create a function to check if the binomial coefficient mod function is well-defined
def binomial2(n, k, mod):
    ans = 1
    if k > n:
        k = n - k
    for i in range(1, k+1):
        num, denum = divmod(n+k-1, i)
        # n-k = k*(n-1)/i
        # now n-k will only add (k-1) since it would be denominator
        # numerator will be greater, so math.floor of numerator is product
        ans = ((ans*(-num + k)) // denum) % mod
    return ans

@lru_cache(maxsize=10**6)
def comb(n, k, m):
    if k * 2 > n:
        return 0
    if n < k:
        return 0
    if n == m:
        return binomial(k, m) % mod
    if n == 0 or k == 0:
        return 1
    if m == 0:
        return binomial(n, m)
    return (comb(n-k, k, m-1) + comb(n-m, k, m-1)) % mod

@lru_cache(maxsize=10**6)
def cnt(n):
    data = [0] * n
    freq = [0] * n
    @lru_cache(maxsize=None)
    def dfs(i):
        if freq[i] == 1:
            return binomial2(i, n-i, m) % mod
        else:
            ans = comb(2, 2, m) % m
            for j in range(i+1, n):
                if prime[i]*prime[j] >= m:
                    ans = 0
                    break
                else:
                    ans = (ans + comb(freq[i], freq[j], m) * dfs(i) ** freq[j]) % m
        return ans
    for i in range(n):
        if i and not i % 2:
            continue
        else:
            primerot = [int(a) for a in str(i)]
            for j in range(len(primerot)):
                freq[primerot[j]] += 1
            freq[i] = 2
            data[i] = dfs(0)
            for j in range(len(primerot)):
                freq[primerot[j]] -= 1
    for i in range(2, n):
        if data[i] == 0:
            L = len(range(2, i//2 + 1) + range(i//2+1, i+1))
            if i not in prime:
                data[i] = L * 2
            else:
                data[i] = (L//2 * data[i-1] + (L & 1)*data[i-2]) % mod
    return data

@lru_cache(maxsize=10**6)
def choose(n, k, m):
    if k == 0:
        return 1
    if k == n:
        return 0
    ans = 1
    md = 16807
    md2 = 444857
    rmd = (md2-1) if m == 2 else (md2-2)

    t = ((n % md) * (m % md) % md2) + (n % 2)
    while ans > 1:
        r = power(t, ans, md2)
        if r == md2 or ans == rmd:
            ans -= 1
        r = power(int(r), k, md)
        ans -= 1
    return r % md

