import sys

def find_min_sortable_array(array_length):
    result = [(i + 1)**array_length for i in range(array_length)]
    min_sum = sum(result)
    if min_sum <= array_length:
        return min_sum, result
    else:
        def is_sorted(nums):
            return nums == sorted(nums)

        def get_next_sortable():
            previous = result
            for i in reversed(range(1, array_length)):
                result[i] = previous[i] * 2 - result[i - 1]
                if result[i] < 1:
                    result[i] = 1
                    result[i - 1] = previous[i - 1] * 2 - result[i]
            return tuple(result)

        next_result = get_next_sortable()
        while next_result != result:
            result = next_result
            next_result = get_next_sortable()

        min_sum = sum(result)
        return min_sum, result

