def find_min_divisible_subsequence(n, k, nums):
    product = 1
    divisible = False

    for i in range(n):
        product *= nums[i]

        if product % k == 0:
            divisible = True
            break

    if not divisible:
        return -1
    else:
        used = [False] * n

        subsequence = []
        for y in range(n):
            if 0 == (product // nums[y]) % k:
                if not used[y]:
                    subsequence.insert(0, y)
                    used[y] = True

        return len(subsequence), subsequence

