        sum_freq_of_followers = sum([
            (1 + len(self.followers)) * frequency
            for frequency in sorted(self.freq.values())
        ])
        return sum_freq_of_followers

class SocialNetwork:
    def __init__(self, num):
        self.num = num
        self.hierarchy = [FanPage(i) for i in range(num)]
        self.freq = defaultdict(int)

    def update_freq(self, follower, follower_freq):
        self.freq[follower] = follower_freq

    def add_follower(self, follower, follower_follower):
        self.hierarchy[follower].follow(follower_follower)

    def total_incomes(self):
