            [self.hierarchy[i].get_income()
             for i in range(self.num)]
        )

    def follow(self, follower, follower_follower):
        self.add_follower(follower, follower_follower)
        parent = self.hierarchy[self.total_num - len(self.hierarchy)]   # the mother and grandmother in addition to grandmother
        self.hierarchy[follower].follow(parent)
        self.add_follower(parent, {follower_follower})

    def calc_big_and_small(self, low_id, low_freq, high_id, high_freq):
        big_income = 0
        small_income = 0
        for i, follower in enumerate(self.hierarchy[low_id + 3]):
