import sys

def dijkstra(graph, start):
    inf = float('inf')
    dist = {i: inf for i in range(1, len(graph)+1)}
    dist[start] = 0
    queue = [(0, start)]

    while queue:
        cur_dist, node = queue.pop(0)

        if dist[node] != cur_dist:
