import sys

def check_feasibility(n, m, q, actions):
    graph = [[False for _ in range(m*m)] for _ in range(n)]
    visited = [[False for _ in range(m*m)] for _ in range(n)]
    num_edges = 0

    for action in actions:
        t, r1, c1, r2, c2 = action
        if t == 1:
            for i in range(r1-1, r2):
                for j in range(c1-1, c2):
                    graph[i][j] = True
            num_edges += 4

        elif t == 2:
            for i in range(r1-1, r2+1):
                for j in range(c1-1, c2+1):
                    graph[i][j] = False
            visited[r1][c1] = True
            visited[r1][c2] = True
            visited[r2][c1] = True
            visited[r2][c2] = True

        elif t == 3:
            for i in range(r1-1, r2+1):
                for j in range(c1-1, c2+1):
                    if graph[i][j]:
                        graph[i][j] = False
                        graph[i][j*(m-2)] = True
                        if not visited[i][j*(m-2)]:
                            num_edges += 1
                        visited[i][j*(m-2)] = True

    if num_edges % 2 == n*m:
        return "Yes"
    else:
        return "No"

