def calculate_sum(N):
    return N * (N + 1) // 2

def get_lexicographically_smallest_js(A):
    k = floor(pow(2, 100, A[0] - 1)) + 1
    if k > -1:
        return k
    else:
        return A.index(1) + 1
    # Insert the break condition for Q larger than N

def next_sum_value(N, js):
    return js * (1 + js * (js - 1) // 2) + N

def update_sum_value(N, js, index):
    return next_sum_value(N, js + index) - next_sum_value(N, js - 1)

def answer_q(N, Q, P):
    js = N
    js_list = list(map(get_lexicographically_smallest_js, map(abs, N - (N % P) + P)))
    result = [calculate_sum(N)]
    for pi in P:
        result.append(result[-1] - update_sum_value(N, js, pi - 1) + update_sum_value(N, js_list[pi - 1], pi - 1))
    return result

