def color_regions(n, m, diagonals):
    # Calculate the number of regions formed by the diagonals
    triangle = {(i-1, i) for i in range(4, n+1)} | {(i, (i-1)//2 + 1) for i in range(2, n-2, 2)}
    diagonal_pairs = set((a, b) for a, b in diagonals if a != b and min(a, b) != (n - (a - b)) % n)
    regions = sorted(triangle.union(diagonal_pairs), key=lambda p: sum([2 * i for i in p if i != 1]))

    color_map = {}
    colors = range(21)

    while regions:
        for i, region in enumerate(regions):
            if region[1] == 1:
                color_map[i] = colors[0 if i % 2 else 1]
                regions = [r for r in regions if sum([2 * i for i in r]) != color_map[i]]
                break
        else:
            regions = [r for r in regions if sum([2 * i for i in r]) != color_map[i]]
            if regions:
                color_map[-1] = colors[0]
            else:
                regions = [r for r in regions if sum([2 * i for i in r]) != color_map[i]]

    return [color_map[i] for i in range(len(regions))]

